-- Issue #6735. Synthetic fixture; table, privilege and membership change
-- rolled back. Reproduces the backend ORM insert, which lists "Id" as DEFAULT.
BEGIN;
ALTER TABLE dflow_prod."Roles" RENAME TO role_create_id_6735_saved;
CREATE TABLE dflow_prod."Roles" (
"Id" integer GENERATED BY DEFAULT AS IDENTITY CONSTRAINT role_create_id_6735_fixture_pk PRIMARY KEY,
"Name" varchar(255) NOT NULL,
kind text NOT NULL DEFAULT 'leaf',
parent_id integer,
is_active boolean NOT NULL DEFAULT true,
app_role_id uuid
);
GRANT SELECT ON dflow_prod."Roles" TO designflow_prod_backend_grants;
DO $setup$
BEGIN
IF NOT pg_has_role(current_user, 'designflow_prod_backend_runtime', 'SET') THEN
EXECUTE format('GRANT designflow_prod_backend_runtime TO %I WITH SET TRUE', current_user);
END IF;
END
$setup$;
\ir ../migrations/20261219003000_dflow_prod_role_create_insert_grant.sql
\ir ../migrations/20261223120000_dflow_prod_role_create_insert_id_grant.sql
DO $contract$
DECLARE new_id integer;
BEGIN
IF has_column_privilege('designflow_prod_backend_runtime','dflow_prod."Roles"','app_role_id','INSERT') THEN
RAISE EXCEPTION 'Runtime must not insert app_role_id';
END IF;
IF has_table_privilege('designflow_prod_backend_runtime','dflow_prod."Roles"','DELETE') THEN
RAISE EXCEPTION 'Runtime must not DELETE';
END IF;
SET LOCAL ROLE designflow_prod_backend_runtime;
INSERT INTO dflow_prod."Roles" ("Id","Name",kind,parent_id,is_active)
VALUES (DEFAULT,'contract-6735-orm-leaf','leaf',NULL,true)
RETURNING "Id" INTO new_id;
RESET ROLE;
IF new_id IS NULL THEN RAISE EXCEPTION 'ORM-shaped insert returned no id'; END IF;
END
$contract$;
ROLLBACK;
